select id, user_id, user_name, user_avatar, university_id, university_name, parent_id, reply_user_id, reply_user_name, content, like_count, status, create_time from t_comment where root_id = #{rootId}
and ( create_time < #{cursor.createTime} or ( create_time = #{cursor.createTime} and id < #{cursor.id} ) )
