WITH RECURSIVE comment_tree AS (
SELECT id, user_id, user_name, user_avatar, university_id, university_name, root_id, parent_id, reply_user_id, reply_user_name, content, like_count, status, create_time, 0 AS depth
FROM t_comment WHERE id = #{startId}
UNION ALL
SELECT c.id, c.user_id, c.user_name, c.user_avatar, c.university_id, c.university_name, c.root_id, c.parent_id, c.reply_user_id, c.reply_user_name, c.content, c.like_count, c.status, c.create_time, ct.depth + 1
FROM comment_tree ct JOIN t_comment c ON ct.id = c.parent_id WHERE ct.depth < #{maxDepth}
)
SELECT id, user_id, user_name, user_avatar, university_id, university_name, root_id, parent_id, reply_user_id, reply_user_name, content, like_count, status, create_time
FROM comment_tree
ORDER BY create_time ASC, id ASC
LIMIT #{maxNodeCount}

